//! A loopback HTTP/1.1 server of files by path, for the files `dedensd` downloads, and IANA's TLD list to serve.

use std::collections::HashMap;
use std::io::{BufRead, BufReader, Write};
use std::net::{SocketAddr, TcpListener};
use std::sync::{Arc, Mutex, PoisonError};
use std::thread;
use std::time::{SystemTime, UNIX_EPOCH};

use serde_json::Value;

/// IANA's TLD list as bundled, captured by `just roots`, its `meta.generated` edited to now: generated by IANA
/// that day, it is 30 days from stale (D128), whatever the age of the bundled one.
pub(crate) fn tld_list() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../crates/dedens-roots/src/tlds.json"
    );
    let mut list: Value =
        serde_json::from_slice(&std::fs::read(path).expect("the bundled list")).expect("JSON");
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("after 1970");
    list["meta"]["generated"] = utc(now.as_secs()).into();
    list
}

/// `seconds` since 1970 as `YYYY-MM-DDTHH:MM:SSZ` (Howard Hinnant's `civil_from_days`).
fn utc(seconds: u64) -> String {
    let (days, time) = (seconds / 86_400, seconds % 86_400);
    // Days from 0000-03-01, in eras of 400 years.
    let days = days + 719_468;
    let (era, day_of_era) = (days / 146_097, days % 146_097);
    let year_of_era =
        (day_of_era - day_of_era / 1460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let shifted_month = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * shifted_month + 2) / 5 + 1;
    let (month, year) = if shifted_month < 10 {
        (shifted_month + 3, year_of_era + era * 400)
    } else {
        (shifted_month - 9, year_of_era + era * 400 + 1)
    };
    format!(
        "{year:04}-{month:02}-{day:02}T{:02}:{:02}:{:02}Z",
        time / 3600,
        time % 3600 / 60,
        time % 60
    )
}

/// Serves each file it holds with 200 and no version tag, 404 for any other path; one request a connection.
pub(crate) struct Files {
    pub(crate) addr: SocketAddr,
    files: Arc<Mutex<HashMap<String, Vec<u8>>>>,
}

impl Files {
    pub(crate) fn start() -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").expect("a TCP port");
        let addr = listener.local_addr().expect("its address");
        let files = Arc::new(Mutex::new(HashMap::<String, Vec<u8>>::new()));
        let shared = Arc::clone(&files);
        thread::spawn(move || {
            for mut stream in listener.incoming().flatten() {
                let mut lines = BufReader::new(&stream).lines().map_while(Result::ok);
                let path = lines
                    .next()
                    .and_then(|line| line.split(' ').nth(1).map(str::to_owned))
                    .unwrap_or_default();
                // The headers, read to the blank line ending them.
                lines.find(String::is_empty);
                let files = shared.lock().unwrap_or_else(PoisonError::into_inner);
                let (status, body) = files
                    .get(&path)
                    .map_or((404, &[][..]), |body| (200, body.as_slice()));
                let head = format!(
                    "HTTP/1.1 {status} X\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                    body.len()
                );
                let _ = stream.write_all(head.as_bytes());
                let _ = stream.write_all(body);
            }
        });
        Self { addr, files }
    }

    /// Serves `body` at `path`, from `/`.
    pub(crate) fn serve(&self, path: &str, body: impl Into<Vec<u8>>) {
        let mut files = self.files.lock().unwrap_or_else(PoisonError::into_inner);
        files.insert(path.to_owned(), body.into());
    }

    /// The URL of `path`.
    pub(crate) fn url(&self, path: &str) -> String {
        format!("http://{}{path}", self.addr)
    }
}
